import contextlib
import io
import itertools
import json
import sys
from types import SimpleNamespace

CODE_PATH = "block-0.txt"
CASES_PATH = "inputs.json"
TOL = 1e-9
MAX_VARS = 24


def emit(obj):
    sys.stdout.write(json.dumps(obj))
    sys.stdout.write("\n")
    sys.stdout.flush()


class _Groups:
    def __init__(self, classes):
        self._keys = list(classes)

    def keys(self):
        return list(self._keys)


class _Series:
    def __init__(self, values):
        self._values = list(values)

    def tolist(self):
        return list(self._values)


class _Frame:
    def __init__(self, instructors):
        self._instructors = list(instructors)

    def __getitem__(self, key):
        if key != "V_ID_NAME_CONCAT":
            raise KeyError(key)
        return _Series(self._instructors)


def measure(pyo, m):
    constraints = list(
        m.component_data_objects(pyo.Constraint, active=True, descend_into=True)
    )
    variables = list(m.component_data_objects(pyo.Var, descend_into=True))
    n = len(variables)
    if n > MAX_VARS:
        raise RuntimeError("too many variables for exhaustive check: %d" % n)

    feasible = 0
    for bits in itertools.product((0, 1), repeat=n):
        for v, b in zip(variables, bits):
            v.set_value(b, skip_validation=True)
        ok = True
        for con in constraints:
            body = pyo.value(con.body)
            if con.lower is not None and body < pyo.value(con.lower) - TOL:
                ok = False
                break
            if con.upper is not None and body > pyo.value(con.upper) + TOL:
                ok = False
                break
        if ok:
            feasible += 1

    return {
        "constraint_count": len(constraints),
        "feasible_assignments": feasible,
    }


def run_candidate(pyo, code, classes, instructors):
    ns = {"__name__": "__candidate__"}
    ns["gb_courses"] = SimpleNamespace(groups=_Groups(classes))
    ns["df_TT_instructors_FALL"] = _Frame(instructors)
    exec(compile(code, CODE_PATH, "exec"), ns)
    m = ns.get("m")
    if m is None:
        raise RuntimeError("candidate did not define m")
    return measure(pyo, m)


def main():
    try:
        with open(CASES_PATH, "r", encoding="utf-8") as fh:
            cases = json.load(fh)
    except Exception as exc:
        emit({"results": [], "harness_error": "failed to read inputs.json: " + repr(exc)})
        return

    try:
        with open(CODE_PATH, "r", encoding="utf-8") as fh:
            code = fh.read()
    except Exception as exc:
        emit({"results": [], "harness_error": "failed to read block-0.txt: " + repr(exc)})
        return

    try:
        with contextlib.redirect_stdout(io.StringIO()):
            import pyomo.environ as pyo
    except Exception as exc:
        emit({"results": [], "harness_error": "failed to import pyomo: " + repr(exc)})
        return

    results = []
    for case in cases:
        cid = case.get("id") if isinstance(case, dict) else None
        try:
            inp = case["input"]
            classes = list(inp["classes"])
            instructors = list(inp["instructors"])
        except Exception as exc:
            results.append({"id": cid, "error": "bad input: " + repr(exc)})
            continue

        buf = io.StringIO()
        try:
            with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
                actual = run_candidate(pyo, code, classes, instructors)
            results.append({"id": cid, "actual": actual})
        except Exception as exc:
            results.append({"id": cid, "error": type(exc).__name__ + ": " + str(exc)})

    emit({"results": results})


if __name__ == "__main__":
    main()

import json
import sys
import io
import itertools
import contextlib
from types import SimpleNamespace


def run_candidate(classes, instructors, src, pyo):
    gb = SimpleNamespace(groups=list(classes))
    df = {'V_ID_NAME_CONCAT': list(instructors)}
    g = {'__name__': '__candidate__', 'gb_courses': gb, 'df_TT_instructors_FALL': df}
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
        exec(compile(src, 'block-0.txt', 'exec'), g)
        m = g['m']
        var = m.class_assignments
        cons = m.one_instructor_constraint
        var_keys = list(var.keys())
        constraint_count = len(cons)
        feasible = 0
        for combo in itertools.product((0, 1), repeat=len(var_keys)):
            for k, v in zip(var_keys, combo):
                var[k].set_value(v)
            ok = True
            for idx in list(cons.keys()):
                c = cons[idx]
                body = pyo.value(c.body)
                if c.lower is not None and body < pyo.value(c.lower) - 1e-9:
                    ok = False
                if c.upper is not None and body > pyo.value(c.upper) + 1e-9:
                    ok = False
            if ok:
                feasible += 1
    return {'constraint_count': constraint_count, 'feasible_assignments': feasible}


def main():
    try:
        with open('block-0.txt', 'r', encoding='utf-8') as f:
            src = f.read()
        with open('inputs.json', 'r', encoding='utf-8') as f:
            items = json.load(f)
        import pyomo.environ as pyo
    except Exception as e:
        sys.stdout.write(json.dumps({'results': [], 'harness_error': 'setup failed: ' + type(e).__name__ + ': ' + str(e)}) + '\n')
        return

    results = []
    for item in items:
        iid = item.get('id')
        inp = item.get('input') or {}
        try:
            actual = run_candidate(inp.get('classes', []), inp.get('instructors', []), src, pyo)
            results.append({'id': iid, 'actual': actual})
        except Exception as e:
            results.append({'id': iid, 'error': type(e).__name__ + ': ' + str(e)})
    sys.stdout.write(json.dumps({'results': results}) + '\n')


if __name__ == '__main__':
    main()
